    print(dijkstra(graph, 0))  # {0:0, 1:3, 2:1, 3:4}

"""
Trie (Prefix Tree) — Advanced Implementation
Insert: O(m) | Search: O(m) | m = word length

Applications: autocomplete, spell check, IP routing, word search.
"""

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False
        self.count = 0  # count of words with this prefix

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
            node.count += 1
        node.is_end = True

    def search(self, word):
        node = self.root
        for char in word:
            if char not in node.children: return False
            node = node.children[char]
        return node.is_end

    def starts_with(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children: return False
            node = node.children[char]
        return True

    def count_prefix(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children: return 0
            node = node.children[char]
        return node.count

    def autocomplete(self, prefix):
        """Return all words with given prefix."""
        node = self.root
        for char in prefix:
            if char not in node.children: return []
            node = node.children[char]
        result = []
        def dfs(node, path):
            if node.is_end: result.append(prefix[:-len(path)] + path if path else prefix)
            for c, child in node.children.items():
                dfs(child, path + c)
        def dfs2(node, current):
            if node.is_end: result.append(current)
            for c, child in node.children.items():
                dfs2(child, current + c)
        dfs2(node, prefix)
        return result

    def delete(self, word):
        def _delete(node, word, depth):
            if depth == len(word):
                if node.is_end: node.is_end = False
                return len(node.children) == 0
            char = word[depth]
            if char not in node.children: return False
            should_delete = _delete(node.children[char], word, depth + 1)
            if should_delete:
                del node.children[char]
                return len(node.children) == 0 and not node.is_end
            return False
        _delete(self.root, word, 0)


# Word Search II (Trie + DFS on board)
def find_words(board, words):
    trie = Trie()
    for word in words: trie.insert(word)
    rows, cols = len(board), len(board[0])
    result = set()

    def dfs(node, r, c, path):
        if r < 0 or r >= rows or c < 0 or c >= cols: return
        ch = board[r][c]
        if ch == '#' or ch not in node.children: return
        node = node.children[ch]
        path += ch
        if node.is_end: result.add(path)
        board[r][c] = '#'
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            dfs(node, r+dr, c+dc, path)
        board[r][c] = ch

    for r in range(rows):
        for c in range(cols):
            dfs(trie.root, r, c, '')
    return list(result)


if __name__ == '__main__':
    t = Trie()
    for w in ['apple', 'app', 'application', 'apply', 'apt']:
        t.insert(w)
    print(t.autocomplete('app'))      # ['app', 'apple', 'application', 'apply']
    print(t.count_prefix('app'))      # 4
    print(t.search('apple'))          # True

"""
Heap / Priority Queue — Common Patterns
Push/Pop: O(log n) | Peek: O(1) | Heapify: O(n)
"""

import heapq
from collections import Counter

# 1. Kth Largest Element
def kth_largest(nums, k):
    heap = []
    for num in nums:
        heapq.heappush(heap, num)
        if len(heap) > k:
            heapq.heappop(heap)
    return heap[0]

# 2. Top K Frequent Elements
def top_k_frequent(nums, k):
    count = Counter(nums)
    return heapq.nlargest(k, count, key=count.get)

# 3. K Closest Points to Origin
def k_closest(points, k):
    return heapq.nsmallest(k, points, key=lambda p: p[0]**2 + p[1]**2)

# 4. Merge K Sorted Lists
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val; self.next = next
    def __lt__(self, other): return self.val < other.val

def merge_k_lists(lists):
    heap = []
    for i, node in enumerate(lists):
        if node: heapq.heappush(heap, node)
    dummy = curr = ListNode()
    while heap:
        node = heapq.heappop(heap)
        curr.next = node
        curr = curr.next
        if node.next: heapq.heappush(heap, node.next)
    return dummy.next

# 5. Task Scheduler
def least_interval(tasks, n):
    count = Counter(tasks)
    heap = [-c for c in count.values()]
    heapq.heapify(heap)
    time = 0
    from collections import deque
    cooldown = deque()  # (ready_time, -count)
    while heap or cooldown:
        time += 1
        if heap:
            cnt = heapq.heappop(heap) + 1  # do task
            if cnt: cooldown.append((time + n, cnt))
        if cooldown and cooldown[0][0] == time:
            heapq.heappush(heap, cooldown.popleft()[1])
    return time

# 6. Find Median from Data Stream
class MedianFinder:
    def __init__(self):
        self.lo = []  # max-heap (negated)
        self.hi = []  # min-heap

    def add_num(self, num):
        heapq.heappush(self.lo, -num)
        heapq.heappush(self.hi, -heapq.heappop(self.lo))
        if len(self.hi) > len(self.lo):
            heapq.heappush(self.lo, -heapq.heappop(self.hi))

    def find_median(self):
        if len(self.lo) > len(self.hi): return -self.lo[0]
        return (-self.lo[0] + self.hi[0]) / 2


if __name__ == '__main__':
    print(kth_largest([3,2,1,5,6,4], 2))            # 5
    print(top_k_frequent([1,1,1,2,2,3], 2))          # [1,2]
    print(k_closest([[1,3],[-2,2],[2,4]], 1))         # [[-2,2]]
    mf = MedianFinder()
    for n in [1,2,3]: mf.add_num(n)
    print(mf.find_median())                           # 2.0
